/**
 * The format FHIR R4 defines for each primitive type it constrains further than a JSON string, and
 * the codes of every required binding of an element of type `code` to a value set R4 defines, as the
 * R4 (4.0.1) definitions publish them (retrieved from `https://hl7.org/fhir/R4/profiles-types.json`, `https://hl7.org/fhir/R4/profiles-resources.json`, `https://hl7.org/fhir/R4/valuesets.json`).
 *
 * Generated by `scripts/fhir-element-names.ts` and then formatted; refresh by running it, never by hand.
 *
 * @packageDocumentation
 * @internal
 */

/** Every primitive type R4 constrains further than a JSON string. @internal */
export type FhirFormattedPrimitive =
  | "base64Binary"
  | "boolean"
  | "canonical"
  | "code"
  | "date"
  | "dateTime"
  | "decimal"
  | "id"
  | "instant"
  | "integer"
  | "oid"
  | "positiveInt"
  | "time"
  | "unsignedInt"
  | "uri"
  | "url"
  | "uuid";

/**
 * The format of each primitive type: the pattern its definition carries on its `value` (matched
 * against the whole value), and for an integer kind the range its definition, or the `integer` it
 * derives from, gives. @internal
 */
export const FHIR_PRIMITIVE_FORMATS: Readonly<
  Record<
    FhirFormattedPrimitive,
    { readonly pattern: string; readonly min?: number; readonly max?: number }
  >
> = {
  base64Binary: { pattern: "(\\s*([0-9a-zA-Z\\+/=]){4}\\s*)+" },
  boolean: { pattern: "true|false" },
  canonical: { pattern: "\\S*" },
  code: { pattern: "[^\\s]+(\\s[^\\s]+)*" },
  date: {
    pattern:
      "([0-9]([0-9]([0-9][1-9]|[1-9]0)|[1-9]00)|[1-9]000)(-(0[1-9]|1[0-2])(-(0[1-9]|[1-2][0-9]|3[0-1]))?)?",
  },
  dateTime: {
    pattern:
      "([0-9]([0-9]([0-9][1-9]|[1-9]0)|[1-9]00)|[1-9]000)(-(0[1-9]|1[0-2])(-(0[1-9]|[1-2][0-9]|3[0-1])(T([01][0-9]|2[0-3]):[0-5][0-9]:([0-5][0-9]|60)(\\.[0-9]+)?(Z|(\\+|-)((0[0-9]|1[0-3]):[0-5][0-9]|14:00)))?)?)?",
  },
  decimal: { pattern: "-?(0|[1-9][0-9]*)(\\.[0-9]+)?([eE][+-]?[0-9]+)?" },
  id: { pattern: "[A-Za-z0-9\\-\\.]{1,64}" },
  instant: {
    pattern:
      "([0-9]([0-9]([0-9][1-9]|[1-9]0)|[1-9]00)|[1-9]000)-(0[1-9]|1[0-2])-(0[1-9]|[1-2][0-9]|3[0-1])T([01][0-9]|2[0-3]):[0-5][0-9]:([0-5][0-9]|60)(\\.[0-9]+)?(Z|(\\+|-)((0[0-9]|1[0-3]):[0-5][0-9]|14:00))",
  },
  integer: { pattern: "-?([0]|([1-9][0-9]*))", min: -2147483648, max: 2147483647 },
  oid: { pattern: "urn:oid:[0-2](\\.(0|[1-9][0-9]*))+" },
  positiveInt: { pattern: "[1-9][0-9]*", min: -2147483648, max: 2147483647 },
  time: { pattern: "([01][0-9]|2[0-3]):[0-5][0-9]:([0-5][0-9]|60)(\\.[0-9]+)?" },
  unsignedInt: { pattern: "[0]|([1-9][0-9]*)", min: -2147483648, max: 2147483647 },
  uri: { pattern: "\\S*" },
  url: { pattern: "\\S*" },
  uuid: { pattern: "urn:uuid:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}" },
};

